static uint32_t payload_crc(const struct vg_config *cfg)
{
  char buf[128];
  int n;

  n = snprintf(buf, sizeof(buf), "%u|%u|%d|%s",
               (unsigned)cfg->schema_version,
               (unsigned)cfg->seq,
               cfg->committed ? 1 : 0,
               cfg->device_name);
  if (n <= 0 || (size_t)n >= sizeof(buf))
    {
      return 0;
    }

  return crc32_update(0, (const uint8_t *)buf, (size_t)n);
}

void vg_config_set_basedir(const char *dir)
{
  if (dir == NULL || dir[0] == '\0')
    {
      g_basedir[0] = '\0';
      return;
    }

  snprintf(g_basedir, sizeof(g_basedir), "%s", dir);
}

void vg_config_factory_default(struct vg_config *out)
{
  memset(out, 0, sizeof(*out));
  out->schema_version = VG_CFG_SCHEMA_VERSION;
  out->seq = 0;
  out->committed = true;
  snprintf(out->device_name, sizeof(out->device_name), "factory");
}

static int slot_path(int slot, char *out, size_t outlen)
{
  const char *name = (slot == 0) ? VG_CFG_SLOT_A_NAME : VG_CFG_SLOT_B_NAME;

  if (g_basedir[0] == '\0')
    {
      return -EINVAL;
    }

  snprintf(out, outlen, "%s/%s", g_basedir, name);
  return 0;
}

static int ensure_basedir(void)
{
  struct stat st;

  if (g_basedir[0] == '\0')
    {
      return -EINVAL;
    }

  if (stat(g_basedir, &st) == 0)
    {
      return S_ISDIR(st.st_mode) ? 0 : -ENOTDIR;
    }

  /* mkdir -p style: only one level under mount for bring-up path
   * .../velaguard then .../velaguard/config
   */

  {
    char tmp[256];
    char *slash;

    snprintf(tmp, sizeof(tmp), "%s", g_basedir);
    slash = strchr(tmp + 1, '/');
    while (slash != NULL)
      {
        *slash = '\0';
        if (stat(tmp, &st) != 0)
          {
            if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
              {
                return -errno;
              }
          }

        *slash = '/';
        slash = strchr(slash + 1, '/');
      }

    if (mkdir(g_basedir, 0755) != 0 && errno != EEXIST)
      {
        return -errno;
      }
  }

  return 0;
}

static int read_slot(int slot, struct vg_config *out, uint32_t *crc_out)
{
  char path[300];
  char line[256];
  FILE *fp;
  unsigned schema = 0;
  unsigned seq = 0;
  unsigned committed = 0;
  unsigned crc = 0;
  char name[VG_CFG_DEVICE_NAME_MAX + 1];
  int n;
  uint32_t expect;

  if (slot_path(slot, path, sizeof(path)) != 0)
    {
      return -EINVAL;
    }

  fp = fopen(path, "r");
  if (fp == NULL)
    {
      return -ENOENT;
    }

  if (fgets(line, sizeof(line), fp) == NULL)
    {
      fclose(fp);
      return -EIO;
    }

  fclose(fp);

  name[0] = '\0';
  n = sscanf(line,
             "{\"schema_version\":%u,\"seq\":%u,\"committed\":%u,"
             "\"crc32\":%u,\"device_name\":\"%31[^\"]\"}",
             &schema, &seq, &committed, &crc, name);
  if (n != 5)
    {
      return -EINVAL;
    }

  memset(out, 0, sizeof(*out));
  out->schema_version = schema;
  out->seq = seq;
  out->committed = (committed != 0);
  snprintf(out->device_name, sizeof(out->device_name), "%s", name);

  expect = payload_crc(out);
  if (crc_out)
    {
      *crc_out = expect;
    }

  if (crc != expect)
    {
      return -EINVAL;
    }

  if (out->schema_version != VG_CFG_SCHEMA_VERSION)
    {
      return -EINVAL;
    }

  if (!out->committed)
    {
      return -EINVAL;
    }

  return 0;
}

static int write_slot_raw(int slot, const struct vg_config *cfg)
{
  char path[300];
  char tmppath[320];
  FILE *fp;
  uint32_t crc;
  int fd;
  int ret;

  ret = slot_path(slot, path, sizeof(path));
  if (ret != 0)
    {
      return ret;
    }

  snprintf(tmppath, sizeof(tmppath), "%s.tmp", path);
  crc = payload_crc(cfg);

  fp = fopen(tmppath, "w");
  if (fp == NULL)
    {
      return -errno;
    }

  if (fprintf(fp,
              "{\"schema_version\":%u,\"seq\":%u,\"committed\":%u,"
              "\"crc32\":%u,\"device_name\":\"%s\"}\n",
              (unsigned)cfg->schema_version,
              (unsigned)cfg->seq,
              cfg->committed ? 1u : 0u,
              (unsigned)crc,
              cfg->device_name) < 0)
    {
      fclose(fp);
      unlink(tmppath);
      return -EIO;
    }

  fflush(fp);
  fd = fileno(fp);
  if (fd >= 0)
    {
      fsync(fd);
    }

  if (fclose(fp) != 0)
    {
      unlink(tmppath);
      return -EIO;
    }

  if (rename(tmppath, path) != 0)
    {
      unlink(tmppath);
      return -errno;
    }

  /* Best-effort directory fsync omitted (not portable). */

  return 0;
}

int vg_config_load(struct vg_config *out)
{
  struct vg_config a;
  struct vg_config b;
  int ra;
  int rb;
  bool a_ok;
  bool b_ok;

  if (out == NULL)
    {
      return -EINVAL;
    }

  ra = read_slot(0, &a, NULL);
  rb = read_slot(1, &b, NULL);
  a_ok = (ra == 0);
  b_ok = (rb == 0);

  if (a_ok && b_ok)
    {
      *out = (a.seq >= b.seq) ? a : b;
      return 0;
    }

  if (a_ok)
    {
      *out = a;
      return 0;
    }

  if (b_ok)
    {
      *out = b;
      return 0;
    }

  vg_config_factory_default(out);
  VG_CFG_LOG("vgcfg: both slots invalid; factory default\n");
  return 1;
}

int vg_config_commit(const struct vg_config *in)
{
  struct vg_config cur;
  struct vg_config next;
  int load_ret;
  int inactive;
  uint32_t max_seq = 0;
  struct vg_config a;
  struct vg_config b;
  int ra;
  int rb;

  if (in == NULL)
    {
      return -EINVAL;
    }

  load_ret = ensure_basedir();
  if (load_ret != 0)
    {
      return load_ret;
    }

  ra = read_slot(0, &a, NULL);
  rb = read_slot(1, &b, NULL);
  if (ra == 0 && a.seq > max_seq)
    {
      max_seq = a.seq;
    }

  if (rb == 0 && b.seq > max_seq)
    {
      max_seq = b.seq;
    }

  /* Prefer writing the slot that is not currently selected. */

  load_ret = vg_config_load(&cur);
  if (load_ret < 0)
    {
      return load_ret;
    }

  if (ra == 0 && rb == 0)
    {
      inactive = (cur.seq == a.seq && strcmp(cur.device_name, a.device_name) == 0)
                   ? 1 : 0;
      /* If equal seq content ambiguous, pick lower seq file as inactive. */
      if (a.seq == b.seq)
        {
          inactive = 1;
        }
      else if (a.seq > b.seq)
        {
          inactive = 1;
        }
      else
        {
          inactive = 0;
        }
    }
  else if (ra == 0)
    {
      inactive = 1;
    }
  else if (rb == 0)
    {
      inactive = 0;
    }
  else
    {
      inactive = 0;
    }

  next = *in;
  next.schema_version = VG_CFG_SCHEMA_VERSION;
  next.seq = max_seq + 1;
  next.committed = false;

  load_ret = write_slot_raw(inactive, &next);
  if (load_ret != 0)
    {
      return load_ret;
    }

  next.committed = true;
  load_ret = write_slot_raw(inactive, &next);
  if (load_ret != 0)
    {
      return load_ret;
    }

  /* Read-back verify */

  {
    struct vg_config verify;
    int vr = read_slot(inactive, &verify, NULL);
    if (vr != 0 || verify.seq != next.seq ||
        strcmp(verify.device_name, next.device_name) != 0)
      {
        return -EIO;
      }
  }

  return 0;
}

int vg_config_damage_slot(int slot, int mode)
{
  char path[300];
  FILE *fp;
  int ret;

  if (slot != 0 && slot != 1)
    {
      return -EINVAL;
    }

  ret = slot_path(slot, path, sizeof(path));
  if (ret != 0)
    {
      return ret;
    }

  if (mode == 0)
    {
      fp = fopen(path, "w");
      if (fp == NULL)
        {
          return -errno;
        }

      fclose(fp);
      return 0;
    }

  if (mode == 1)
    {
      char line[256];
      size_t len;

      fp = fopen(path, "r+");
      if (fp == NULL)
        {
          return -errno;
        }

      if (fgets(line, sizeof(line), fp) == NULL)
        {
          fclose(fp);
          return -EIO;
        }

      len = strlen(line);
      if (len > 10)
        {
          line[len / 2] ^= 0x55;
        }

      rewind(fp);
      fputs(line, fp);
      fflush(fp);
      fsync(fileno(fp));
      fclose(fp);
      return 0;
    }

  return -EINVAL;
}

