/* CRC-32 (ISO 3309 / Ethernet), bit-wise — matches common lib_crc32. */

static uint32_t crc32_update(uint32_t crc, const uint8_t *data, size_t len)
{
  size_t i;
  int bit;

  crc = ~crc;
  for (i = 0; i < len; i++)
    {
      crc ^= data[i];
      for (bit = 0; bit < 8; bit++)
        {
          if (crc & 1u)
            {
              crc = (crc >> 1) ^ 0xedb88320u;
            }
          else
            {
              crc >>= 1;
            }
        }
    }

  return ~crc;
}

