static int ensure_basedir(void)
{
  struct stat st;
  char tmp[256];
  char *p;

  if (g_basedir[0] == '\0')
    {
      return -EINVAL;
    }

  if (stat(g_basedir, &st) == 0)
    {
      return S_ISDIR(st.st_mode) ? 0 : -ENOTDIR;
    }

  /* mkdir -p: create each component of g_basedir. */

  snprintf(tmp, sizeof(tmp), "%s", g_basedir);
  for (p = tmp + 1; *p != '\0'; p++)
    {
      if (*p != '/')
        {
          continue;
        }

      *p = '\0';
      if (stat(tmp, &st) != 0)
        {
          if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
            {
              return -errno;
            }
        }
      else if (!S_ISDIR(st.st_mode))
        {
          return -ENOTDIR;
        }

      *p = '/';
    }

  if (mkdir(g_basedir, 0755) != 0 && errno != EEXIST)
    {
      return -errno;
    }

  if (stat(g_basedir, &st) != 0 || !S_ISDIR(st.st_mode))
    {
      return -EIO;
    }

  return 0;
}

