    snprintf(tmp, sizeof(tmp), "%s", g_basedir);
    slash = strchr(tmp + 1, '/');
    while (slash != NULL)
      {
        *slash = '\0';
        if (stat(tmp, &st) != 0)
          {
            if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
              {
                return -errno;
              }
          }

        *slash = '/';
        slash = strchr(slash + 1, '/');
      }

    if (mkdir(g_basedir, 0755) != 0 && errno != EEXIST)
      {
        return -errno;
      }
  }

  return 0;
}

