# 设计：帧级质量统计（MVP B）

## 1. 边界

| 层 | 位置 | 职责 |
|----|------|------|
| 统计核 | `vg_frame_stats.c/h` | 分从站窗口、聚合、inject |
| 挂钩 | `modbus_collector.c`（vgmodbus） | 每次读写结束后 `record` |
| 板测 | NSH `vgstats` | dump / inject / reset |
| 单测 | `host_tests/test_frame_stats.c` | 无硬件 |

不做：采集调度重构、Agent 绑定、分位数。

## 2. 数据模型

```c
enum vg_fs_result {
  VG_FS_OK = 0,
  VG_FS_CRC,
  VG_FS_TIMEOUT,
  VG_FS_ECHO,   /* 收到疑似本机回声（可选检测；可先仅 inject） */
  VG_FS_OTHER
};

struct vg_fs_summary {
  uint32_t total;
  uint32_t ok;
  uint32_t crc_err;
  uint32_t timeout;
  uint32_t echo;
  uint32_t other;
  uint32_t lat_min_ms;   /* ok==0 → 无效 */
  uint32_t lat_max_ms;
  uint32_t lat_avg_ms;
};
```

每从站：环形缓冲最近 N 条 `{result, latency_ms}`，或只维护运行总和 + 环形延迟样本。  
MVP 推荐：**计数器 + 对成功延迟维护 min/max/sum/count**（不必存满 N 条结果，窗口用「最近 N 次」时可用环形计数器简化为固定容量事件环）。

默认：`VG_FS_WINDOW=64`，`VG_FS_MAX_SLAVES=8`（按 addr 映射或小表）。

## 3. API

```c
void vg_fs_init(void);
int  vg_fs_record(uint8_t slave, enum vg_fs_result r, uint32_t latency_ms);
int  vg_fs_summary(uint8_t slave, struct vg_fs_summary *out);
int  vg_fs_reset(uint8_t slave);      /* slave=0 → all */
int  vg_fs_inject(uint8_t slave, enum vg_fs_result r, uint32_t latency_ms);
```

`inject` ≡ `record`（板测别名）。

## 4. 挂钩

`vgmodbus` 每次 `nmbs_read_*` 返回后：

- 成功 → `VG_FS_OK` + 测得 ms  
- `NMBS_ERROR_CRC` → `VG_FS_CRC`  
- `NMBS_ERROR_TIMEOUT` → `VG_FS_TIMEOUT`  
- 其它负错误 → `VG_FS_OTHER`  
- 回声：stage0 以 inject 验证计数为主；若 port 层易检测再挂（不阻塞 AC）

## 5. 风险

| 风险 | 应对 |
|------|------|
| 无真实从站 | inject + host 单测仍过 AC1；AC2 用 inject |
| 从站数膨胀 | 固定 MAX_SLAVES；超出返回 `-ENOMEM` |
| avg 溢出 | sum 用 `uint64_t` |

/****************************************************************************
 * app/velaguard/vg_frame_stats.h
 *
 * Per-slave sliding-window Modbus / RS485 frame quality counters (MVP B).
 ****************************************************************************/

#ifndef __APP_VELAGUARD_VG_FRAME_STATS_H
#define __APP_VELAGUARD_VG_FRAME_STATS_H

#include <stdint.h>

#ifndef VG_FS_WINDOW
#  define VG_FS_WINDOW 64
#endif

#ifndef VG_FS_MAX_SLAVES
#  define VG_FS_MAX_SLAVES 8
#endif

enum vg_fs_result
{
  VG_FS_OK = 0,
  VG_FS_CRC,
  VG_FS_TIMEOUT,
  VG_FS_ECHO,
  VG_FS_OTHER
};

struct vg_fs_summary
{
  uint32_t total;
  uint32_t ok;
  uint32_t crc_err;
  uint32_t timeout;
  uint32_t echo;
  uint32_t other;
  uint32_t lat_min_ms;
  uint32_t lat_max_ms;
  uint32_t lat_avg_ms;
};

void vg_fs_init(void);

int vg_fs_record(uint8_t slave, enum vg_fs_result result, uint32_t latency_ms);

int vg_fs_summary(uint8_t slave, struct vg_fs_summary *out);

int vg_fs_reset(uint8_t slave);

int vg_fs_inject(uint8_t slave, enum vg_fs_result result, uint32_t latency_ms);

const char *vg_fs_result_name(enum vg_fs_result result);

#endif /* __APP_VELAGUARD_VG_FRAME_STATS_H */

/****************************************************************************
 * app/velaguard/vg_frame_stats.c
 *
 * Sliding-window frame quality stats per Modbus slave (host-testable).
 ****************************************************************************/

#include "vg_frame_stats.h"

#include <errno.h>
#include <string.h>

struct vg_fs_event
{
  enum vg_fs_result result;
  uint32_t          latency_ms;
};

struct vg_fs_bucket
{
  uint8_t           slave;
  uint8_t           len;
  uint16_t          pos;
  struct vg_fs_event ring[VG_FS_WINDOW];
};

static struct vg_fs_bucket g_buckets[VG_FS_MAX_SLAVES];
static int g_inited;

static struct vg_fs_bucket *find_bucket(uint8_t slave, bool create)
{
  int i;
  struct vg_fs_bucket *free_slot = NULL;

  if (slave == 0)
    {
      return NULL;
    }

  for (i = 0; i < VG_FS_MAX_SLAVES; i++)
    {
      if (g_buckets[i].slave == slave)
        {
          return &g_buckets[i];
        }

      if (g_buckets[i].slave == 0 && free_slot == NULL)
        {
          free_slot = &g_buckets[i];
        }
    }

  if (!create || free_slot == NULL)
    {
      return NULL;
    }

  memset(free_slot, 0, sizeof(*free_slot));
  free_slot->slave = slave;
  return free_slot;
}

static void bucket_reset(struct vg_fs_bucket *b)
{
  if (b == NULL)
    {
      return;
    }

  b->len = 0;
  b->pos = 0;
  memset(b->ring, 0, sizeof(b->ring));
}

const char *vg_fs_result_name(enum vg_fs_result result)
{
  switch (result)
    {
      case VG_FS_OK:
        return "ok";

      case VG_FS_CRC:
        return "crc";

      case VG_FS_TIMEOUT:
        return "timeout";

      case VG_FS_ECHO:
        return "echo";

      default:
        return "other";
    }
}

void vg_fs_init(void)
{
  memset(g_buckets, 0, sizeof(g_buckets));
  g_inited = 1;
}

int vg_fs_record(uint8_t slave, enum vg_fs_result result, uint32_t latency_ms)
{
  struct vg_fs_bucket *b;
  struct vg_fs_event *ev;

  if (!g_inited)
    {
      vg_fs_init();
    }

  b = find_bucket(slave, true);
  if (b == NULL)
    {
      return -ENOMEM;
    }

  ev = &b->ring[b->pos];
  ev->result = result;
  ev->latency_ms = latency_ms;
  b->pos = (uint16_t)((b->pos + 1) % VG_FS_WINDOW);
  if (b->len < VG_FS_WINDOW)
    {
      b->len++;
    }

  return 0;
}

int vg_fs_inject(uint8_t slave, enum vg_fs_result result, uint32_t latency_ms)
{
  return vg_fs_record(slave, result, latency_ms);
}

static void aggregate_bucket(const struct vg_fs_bucket *b,
                             struct vg_fs_summary *out)
{
  unsigned int i;
  uint32_t lat_sum = 0;
  uint32_t lat_cnt = 0;

  memset(out, 0, sizeof(*out));
  out->lat_min_ms = UINT32_MAX;

  if (b == NULL || b->len == 0)
    {
      out->lat_min_ms = 0;
      return;
    }

  for (i = 0; i < b->len; i++)
    {
      unsigned int idx = (unsigned int)((b->pos + VG_FS_WINDOW - b->len + i)
                                        % VG_FS_WINDOW);
      const struct vg_fs_event *ev = &b->ring[idx];

      out->total++;
      switch (ev->result)
        {
          case VG_FS_OK:
            out->ok++;
            if (ev->latency_ms < out->lat_min_ms)
              {
                out->lat_min_ms = ev->latency_ms;
              }

            if (ev->latency_ms > out->lat_max_ms)
              {
                out->lat_max_ms = ev->latency_ms;
              }

            lat_sum += ev->latency_ms;
            lat_cnt++;
            break;

          case VG_FS_CRC:
            out->crc_err++;
            break;

          case VG_FS_TIMEOUT:
            out->timeout++;
            break;

          case VG_FS_ECHO:
            out->echo++;
            break;

          default:
            out->other++;
            break;
        }
    }

  if (lat_cnt == 0)
    {
      out->lat_min_ms = 0;
      out->lat_max_ms = 0;
      out->lat_avg_ms = 0;
    }
  else
    {
      out->lat_avg_ms = lat_sum / lat_cnt;
    }
}

int vg_fs_summary(uint8_t slave, struct vg_fs_summary *out)
{
  struct vg_fs_bucket *b;

  if (out == NULL)
    {
      return -EINVAL;
    }

  if (!g_inited)
    {
      vg_fs_init();
    }

  b = find_bucket(slave, false);
  aggregate_bucket(b, out);
  return 0;
}

int vg_fs_reset(uint8_t slave)
{
  int i;

  if (!g_inited)
    {
      vg_fs_init();
    }

  if (slave == 0)
    {
      for (i = 0; i < VG_FS_MAX_SLAVES; i++)
        {
          g_buckets[i].slave = 0;
          bucket_reset(&g_buckets[i]);
        }

      return 0;
    }

  for (i = 0; i < VG_FS_MAX_SLAVES; i++)
    {
      if (g_buckets[i].slave == slave)
        {
          g_buckets[i].slave = 0;
          bucket_reset(&g_buckets[i]);
          return 0;
        }
    }

  return 0;
}

/****************************************************************************
 * app/velaguard/vgstats.c
 *
 * NSH tool for frame quality stats (bring-up).
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <nuttx/config.h>

#include "vg_frame_stats.h"

static void usage(void)
{
  printf("Usage:\n");
  printf("  vgstats dump [slave]\n");
  printf("  vgstats inject <slave> ok|crc|timeout|echo|other [latency_ms]\n");
  printf("  vgstats reset [slave]\n");
}

static int parse_result(const char *name, enum vg_fs_result *out)
{
  if (strcmp(name, "ok") == 0)
    {
      *out = VG_FS_OK;
      return 0;
    }

  if (strcmp(name, "crc") == 0)
    {
      *out = VG_FS_CRC;
      return 0;
    }

  if (strcmp(name, "timeout") == 0)
    {
      *out = VG_FS_TIMEOUT;
      return 0;
    }

  if (strcmp(name, "echo") == 0)
    {
      *out = VG_FS_ECHO;
      return 0;
    }

  if (strcmp(name, "other") == 0)
    {
      *out = VG_FS_OTHER;
      return 0;
    }

  return -1;
}

static void print_summary(uint8_t slave, const struct vg_fs_summary *s)
{
  printf("vgstats: slave=%u window=%d total=%u ok=%u crc=%u timeout=%u "
         "echo=%u other=%u lat_min=%u lat_max=%u lat_avg=%u\n",
         (unsigned)slave, VG_FS_WINDOW,
         (unsigned)s->total, (unsigned)s->ok, (unsigned)s->crc_err,
         (unsigned)s->timeout, (unsigned)s->echo, (unsigned)s->other,
         (unsigned)s->lat_min_ms, (unsigned)s->lat_max_ms,
         (unsigned)s->lat_avg_ms);
}

/**
  * @brief  NSH: vgstats — frame quality dump / inject / reset.
  */
int main(int argc, char *argv[])
{
  vg_fs_init();

  if (argc < 2)
    {
      usage();
      return 1;
    }

  if (strcmp(argv[1], "dump") == 0)
    {
      if (argc >= 3)
        {
          struct vg_fs_summary s;
          unsigned long slave = strtoul(argv[2], NULL, 0);

          vg_fs_summary((uint8_t)slave, &s);
          print_summary((uint8_t)slave, &s);
          return 0;
        }

      /* Dump all allocated buckets. */

      for (unsigned int i = 1; i <= 247; i++)
        {
          struct vg_fs_summary s;

          vg_fs_summary((uint8_t)i, &s);
          if (s.total > 0)
            {
              print_summary((uint8_t)i, &s);
            }
        }

      return 0;
    }

  if (strcmp(argv[1], "inject") == 0)
    {
      enum vg_fs_result result;
      unsigned long slave;
      unsigned long lat = 0;
      int ret;

      if (argc < 4)
        {
          usage();
          return 1;
        }

      slave = strtoul(argv[2], NULL, 0);
      if (slave < 1 || slave > 247)
        {
          printf("vgstats: slave must be 1..247\n");
          return 1;
        }

      if (parse_result(argv[3], &result) != 0)
        {
          usage();
          return 1;
        }

      if (argc >= 5)
        {
          lat = strtoul(argv[4], NULL, 0);
        }
      else if (result == VG_FS_OK)
        {
          lat = 10;
        }

      ret = vg_fs_inject((uint8_t)slave, result, (uint32_t)lat);
      if (ret != 0)
        {
          printf("vgstats: inject failed %d\n", ret);
          return 1;
        }

      printf("vgstats: injected slave=%lu %s lat=%lu\n",
             slave, vg_fs_result_name(result), lat);
      return 0;
    }

  if (strcmp(argv[1], "reset") == 0)
    {
      unsigned long slave = 0;

      if (argc >= 3)
        {
          slave = strtoul(argv[2], NULL, 0);
        }

      vg_fs_reset((uint8_t)slave);
      printf("vgstats: reset slave=%lu\n", slave);
      return 0;
    }

  usage();
  return 1;
}

/****************************************************************************
 * app/velaguard/host_tests/test_frame_stats.c
 *
 * Host tests for vg_frame_stats (AC1).
 ****************************************************************************/

#include <stdio.h>
#include <stdint.h>

#include "vg_frame_stats.h"

static int g_fail;

static void expect(int cond, const char *msg)
{
  if (!cond)
    {
      fprintf(stderr, "FAIL: %s\n", msg);
      g_fail++;
    }
}

static void test_inject_and_summary(void)
{
  struct vg_fs_summary s;

  vg_fs_reset(0);
  expect(vg_fs_inject(1, VG_FS_OK, 10) == 0, "inject ok");
  expect(vg_fs_inject(1, VG_FS_OK, 30) == 0, "inject ok2");
  expect(vg_fs_inject(1, VG_FS_CRC, 0) == 0, "inject crc");
  expect(vg_fs_inject(1, VG_FS_TIMEOUT, 0) == 0, "inject timeout");
  expect(vg_fs_inject(1, VG_FS_ECHO, 0) == 0, "inject echo");

  vg_fs_summary(1, &s);
  expect(s.total == 5, "total 5");
  expect(s.ok == 2, "ok 2");
  expect(s.crc_err == 1, "crc 1");
  expect(s.timeout == 1, "timeout 1");
  expect(s.echo == 1, "echo 1");
  expect(s.lat_min_ms == 10, "lat min");
  expect(s.lat_max_ms == 30, "lat max");
  expect(s.lat_avg_ms == 20, "lat avg");
}

static void test_window_eviction(void)
{
  struct vg_fs_summary s;
  unsigned int i;

  vg_fs_reset(0);
  for (i = 0; i < VG_FS_WINDOW; i++)
    {
      expect(vg_fs_inject(2, VG_FS_OK, 5) == 0, "fill window");
    }

  expect(vg_fs_inject(2, VG_FS_CRC, 0) == 0, "evict oldest");
  vg_fs_summary(2, &s);
  expect(s.total == VG_FS_WINDOW, "window size");
  expect(s.ok == VG_FS_WINDOW - 1, "one crc after eviction");
  expect(s.crc_err == 1, "crc present");
}

static void test_reset_slave(void)
{
  struct vg_fs_summary s;

  vg_fs_reset(0);
  expect(vg_fs_inject(3, VG_FS_OK, 1) == 0, "seed");
  vg_fs_reset(3);
  vg_fs_summary(3, &s);
  expect(s.total == 0, "reset clears slave");
}

int main(void)
{
  vg_fs_init();
  test_inject_and_summary();
  test_window_eviction();
  test_reset_slave();

  if (g_fail != 0)
    {
      fprintf(stderr, "test_frame_stats: %d failure(s)\n", g_fail);
      return 1;
    }

  printf("test_frame_stats: OK\n");
  return 0;
}

